import { catArt } from './bundledFarm/cat';
import { cowArt } from './bundledFarm/cow';
import { dogArt } from './bundledFarm/dog';
import { duckArt } from './bundledFarm/duck';
import { horseArt } from './bundledFarm/horse';
import { pigArt } from './bundledFarm/pig';
import type { FarmPageId } from './bundledBooks';
import type { PaperTheme } from './theme';
import { artOrientation, type ArtOrientation, type PaperSize } from './paperSpace';

type OutlineNode =
  | Readonly<{ kind: 'path'; d: string }>
  | Readonly<{ kind: 'ellipse'; rx: string; ry: string; transform?: string }>
  | Readonly<{ kind: 'circle'; cx: string; cy: string; r: string }>
  | Readonly<{
      kind: 'rect';
      x: string;
      y: string;
      width: string;
      height: string;
      rx?: string;
      ry?: string;
      transform?: string;
    }>;
export type BundledArtVariant = Readonly<{
  viewBox: string;
  ink: string;
  outline: readonly OutlineNode[];
  fill: string;
}>;
export type BundledPageArt = Readonly<
  Record<ArtOrientation, Readonly<Record<PaperTheme, BundledArtVariant>>> & {
    selector: Readonly<Record<PaperTheme, string>>;
  }
>;

// Canonical SVG geometry and lossless WebP bytes share one offline art source, generated by
// tools/migration/gen-bundled-farm.mjs.
export const BUNDLED_BOOK_ART = {
  'farm/cat': catArt,
  'farm/cow': cowArt,
  'farm/dog': dogArt,
  'farm/duck': duckArt,
  'farm/horse': horseArt,
  'farm/pig': pigArt,
} satisfies Record<FarmPageId, BundledPageArt>;

export function bundledArt(
  pageId: FarmPageId,
  theme: PaperTheme,
  paper: PaperSize
): BundledArtVariant {
  return BUNDLED_BOOK_ART[pageId][artOrientation(paper)][theme];
}

export const BUNDLED_BOOK_COVERS = {
  light:
    'data:image/webp;base64,',
  dark: 'data:image/webp;base64,',
} satisfies Record<PaperTheme, string>;
